 Future<void> load()async{if(_dead||port==null||['loading','saving'].contains(status))return;final g=++_epoch;status='loading';notifyListeners();try{final s=_snapshot(await port!.read(scope,resource));if(_dead||g!=_epoch)return;revision=s.revision;_document=s.document??DashboardLayout.fromJson(defaults.toJson(),widgets,views);loaded=true;status=s.document==null?'ready':'clean';}catch(_){if(_dead||g!=_epoch)return;status='error';}notifyListeners();}
 Future<void> save()async{if(_dead||port==null||!loaded||['loading','saving','conflict'].contains(status)||revision>=9007199254740991)throw StateError('dashboard_unavailable');final key=requestId?.call();if(key==null||!RegExp(r'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',caseSensitive:false).hasMatch(key))throw StateError('request_id_required');final g=++_epoch,edits=_edits,doc=document,rev=revision;status='saving';notifyListeners();try{final acknowledged=_snapshot(await port!.write(scope,resource,rev,doc,key));if(_dead||g!=_epoch)return;if(acknowledged.revision!=rev+1||canonicalPreference(acknowledged.document?.toJson())!=canonicalPreference(doc.toJson()))throw StateError('invalid_acknowledgement');final verified=_snapshot(await port!.read(scope,resource));if(_dead||g!=_epoch)return;if(verified.revision!=acknowledged.revision||canonicalPreference(verified.document?.toJson())!=canonicalPreference(doc.toJson()))throw StateError('readback_mismatch');revision=verified.revision;status=_edits==edits?'clean':'dirty';}catch(e){if(_dead||g!=_epoch)return;status=e is DashboardConflict?'conflict':'error';}notifyListeners();if(['error','conflict'].contains(status))throw StateError('dashboard_save_failed');}
